use vstd::prelude::*;

verus! {
    /// Append `b` to the end of `a` (cloning `a` so `a` is not modified).
    fn append(a: &Vec<i32>, b: i32) -> Vec<i32>
        ensures
            // result length is one more than a
            result.len() == a.len() + 1,
            // for all old indices i < a.len(), result[i] == a[i]
            forall |i: nat| i < a.len() ==> result[i] == a[i],
            // and the new element is at the end
            result[a.len()] == b,
    {
        let mut result = a.clone();
        result.push(b);
        result
    }
}

